import React, { useState, useEffect } from 'react';
import { format, startOfWeek, addDays, isSameDay, startOfMonth, endOfMonth, endOfWeek, eachDayOfInterval, addMonths, subMonths, isToday, addWeeks, subWeeks } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Plus, Check, Pill, Archive, Bell, AlertCircle, Settings as SettingsIcon, Database, RotateCcw, SlidersHorizontal, X } from 'lucide-react';
import { BottomNav } from './components/BottomNav';
import { MedicationForm } from './components/MedicationForm';
import { Medication, MedicationLog, ViewMode, CalendarMode } from './types';
import { LABEL_COLORS, WEEK_DAYS, UNITS, LABELS } from './constants';

const App: React.FC = () => {
  // --- State ---
  const [view, setView] = useState<ViewMode>('home');

  // Calendar State
  const [selectedDate, setSelectedDate] = useState(new Date()); // タスクを表示する日付
  const [displayDate, setDisplayDate] = useState(new Date());   // カレンダーが表示している月/週の基準日
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('week');

  // Data State
  const [medications, setMedications] = useState<Medication[]>([]);
  const [logs, setLogs] = useState<MedicationLog[]>([]);

  // Preferences State
  const [visibleUnits, setVisibleUnits] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('visibleUnits');
      return saved ? JSON.parse(saved) : UNITS;
    } catch { return UNITS; }
  });
  const [visibleLabels, setVisibleLabels] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('visibleLabels');
      return saved ? JSON.parse(saved) : LABELS;
    } catch { return LABELS; }
  });

  // UI State
  const [editingMed, setEditingMed] = useState<Medication | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [showDetailId, setShowDetailId] = useState<string | null>(null);
  const [showCustomizeModal, setShowCustomizeModal] = useState(false);

  // --- Effects (Persistence) ---
  useEffect(() => {
    try {
      const savedMeds = localStorage.getItem('medications');
      const savedLogs = localStorage.getItem('logs');
      if (savedMeds) setMedications(JSON.parse(savedMeds));
      if (savedLogs) setLogs(JSON.parse(savedLogs));
    } catch (e) {
      console.error("Failed to load data", e);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('medications', JSON.stringify(medications));
  }, [medications]);

  useEffect(() => {
    localStorage.setItem('logs', JSON.stringify(logs));
  }, [logs]);

  useEffect(() => {
    localStorage.setItem('visibleUnits', JSON.stringify(visibleUnits));
  }, [visibleUnits]);

  useEffect(() => {
    localStorage.setItem('visibleLabels', JSON.stringify(visibleLabels));
  }, [visibleLabels]);

  // --- Logic Helpers ---
  const handleSaveMed = (med: Medication) => {
    if (editingMed) {
      setMedications(prev => prev.map(m => m.id === med.id ? med : m));
    } else {
      setMedications(prev => [...prev, med]);
    }
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const handleDeleteMed = (id: string) => {
    setMedications(prev => prev.filter(m => m.id !== id));
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const toggleComplete = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    const existingLog = logs.find(l => l.medicationId === medId && l.dateStr === dateStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existingLog) {
      // Untoggle: Remove log and restore stock
      setLogs(prev => prev.filter(l => l.id !== existingLog.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      // Toggle: Add log and decrease stock
      const newLog: MedicationLog = {
        id: crypto.randomUUID(),
        medicationId: medId,
        timestamp: new Date().getTime(),
        dateStr
      };
      setLogs(prev => [...prev, newLog]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  const isCompleted = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dateStr);
  };

  const handleCalendarNavigate = (direction: 'prev' | 'next') => {
    if (calendarMode === 'day') {
      const newDate = direction === 'next' ? addDays(selectedDate, 1) : addDays(selectedDate, -1);
      setSelectedDate(newDate);
      setDisplayDate(newDate);
    } else if (calendarMode === 'week') {
      setDisplayDate(prev => direction === 'next' ? addWeeks(prev, 1) : subWeeks(prev, 1));
    } else {
      setDisplayDate(prev => direction === 'next' ? addMonths(prev, 1) : subMonths(prev, 1));
    }
  };

  // --- Calendar Generators ---
  const generateCalendarDays = () => {
    if (calendarMode === 'day') {
      return [selectedDate];
    }
    if (calendarMode === 'week') {
      const start = startOfWeek(displayDate, { weekStartsOn: 0 }); // Sunday start
      return Array.from({ length: 7 }).map((_, i) => addDays(start, i));
    }
    // Month
    const start = startOfWeek(startOfMonth(displayDate), { weekStartsOn: 0 });
    const end = endOfWeek(endOfMonth(displayDate), { weekStartsOn: 0 });
    return eachDayOfInterval({ start, end });
  };

  const calendarDays = generateCalendarDays();

  // --- Customize Modal ---
  const CustomizeModal = () => {
    const [activeTab, setActiveTab] = useState<'timing' | 'unit'>('timing');

    const toggleUnit = (u: string) => {
      setVisibleUnits(prev => prev.includes(u) ? prev.filter(x => x !== u) : [...prev, u]);
    };

    const toggleLabel = (l: string) => {
      setVisibleLabels(prev => prev.includes(l) ? prev.filter(x => x !== l) : [...prev, l]);
    };

    return (
      <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 animate-in fade-in duration-200">
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowCustomizeModal(false)}></div>
        <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm flex flex-col max-h-[80vh] relative z-10 animate-in zoom-in-95 duration-200">
          <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-2xl">
            <h3 className="font-bold text-slate-800">表示のカスタマイズ</h3>
            <button onClick={() => setShowCustomizeModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
          </div>

          <div className="flex p-2 gap-2 bg-slate-50 border-b border-slate-100">
            <button 
              onClick={() => setActiveTab('timing')}
              className={`flex-1 py-2 text-sm font-bold rounded-lg transition-colors ${activeTab === 'timing' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
            >
              服薬タイミング
            </button>
            <button 
              onClick={() => setActiveTab('unit')}
              className={`flex-1 py-2 text-sm font-bold rounded-lg transition-colors ${activeTab === 'unit' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
            >
              単位
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-2">
            {activeTab === 'timing' ? (
              <div className="space-y-1">
                {LABELS.map(label => (
                  <label key={label} className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 cursor-pointer">
                    <span className="font-bold text-slate-700">{label}</span>
                    <div className="relative inline-flex items-center">
                      <input 
                        type="checkbox" 
                        checked={visibleLabels.includes(label)}
                        onChange={() => toggleLabel(label)}
                        className="sr-only peer" 
                      />
                      <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:bg-emerald-500 after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:after:translate-x-full peer-checked:after:border-white"></div>
                    </div>
                  </label>
                ))}
              </div>
            ) : (
              <div className="space-y-1">
                {UNITS.map(unit => (
                  <label key={unit} className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 cursor-pointer">
                    <span className="font-bold text-slate-700">{unit}</span>
                    <div className="relative inline-flex items-center">
                      <input 
                        type="checkbox" 
                        checked={visibleUnits.includes(unit)}
                        onChange={() => toggleUnit(unit)}
                        className="sr-only peer" 
                      />
                      <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:bg-emerald-500 after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:after:translate-x-full peer-checked:after:border-white"></div>
                    </div>
                  </label>
                ))}
              </div>
            )}
          </div>

          <div className="p-4 border-t border-slate-100 bg-slate-50 rounded-b-2xl">
             <button onClick={() => setShowCustomizeModal(false)} className="w-full bg-emerald-600 text-white font-bold py-3 rounded-xl shadow-lg shadow-emerald-200">完了</button>
          </div>
        </div>
      </div>
    );
  };

  // --- Renders ---

  const renderHome = () => (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Page Header (New) */}
      <div className="bg-slate-50/80 backdrop-blur-sm border-b border-slate-200 py-3 safe-top">
         <h1 className="text-center font-bold text-slate-800">ホーム</h1>
      </div>

      {/* Calendar Header & Control */}
      <div className="bg-white shadow-sm z-10 sticky top-0 rounded-b-3xl border-b border-slate-100">
        <div className="px-5 pt-4 pb-2">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-extrabold text-slate-800 flex items-center gap-2">
              <CalendarIcon className="text-emerald-600" size={24} />
              {calendarMode === 'day' 
                ? format(selectedDate, 'M月d日', { locale: ja }) 
                : format(displayDate, 'yyyy年 M月', { locale: ja })}
            </h2>
            <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1">
               <button 
                  onClick={() => setCalendarMode('month')} 
                  className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${calendarMode === 'month' ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>月</button>
               <button 
                  onClick={() => {
                    setCalendarMode('week');
                    setDisplayDate(selectedDate);
                  }} 
                  className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${calendarMode === 'week' ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>週</button>
               <button 
                  onClick={() => {
                    setCalendarMode('day');
                    setDisplayDate(selectedDate);
                  }} 
                  className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${calendarMode === 'day' ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>日</button>
            </div>
          </div>

          <div className="flex justify-between items-center mb-2">
             <button onClick={() => handleCalendarNavigate('prev')} className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors"><ChevronLeft size={20}/></button>
             <button onClick={() => {
               const now = new Date();
               setSelectedDate(now);
               setDisplayDate(now);
             }} className="text-xs font-bold text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full hover:bg-emerald-100 transition-colors">今日に戻る</button>
             <button onClick={() => handleCalendarNavigate('next')} className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors"><ChevronRight size={20}/></button>
          </div>

          <div className={`grid ${calendarMode === 'month' ? 'grid-cols-7 gap-y-1' : calendarMode === 'week' ? 'grid-cols-7' : 'grid-cols-1'} text-center pb-4`}>
            {calendarMode !== 'day' && WEEK_DAYS.map((day, i) => (
              <div key={day} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{day}</div>
            ))}

            {calendarDays.map((day, idx) => {
              const isSelected = isSameDay(day, selectedDate);
              const isTodayDate = isToday(day);
              const isCurrentMonth = calendarMode !== 'month' || format(day, 'M') === format(displayDate, 'M');

              const dayStr = format(day, 'yyyy-MM-dd');
              const medsForDay = medications.length;
              const completedCount = logs.filter(l => l.dateStr === dayStr && medications.some(m => m.id === l.medicationId)).length;
              const allDone = medsForDay > 0 && medsForDay === completedCount;
              const someDone = completedCount > 0;

              if (calendarMode === 'day') {
                return (
                  <div key={idx} className="flex flex-col items-center justify-center py-6 animate-in fade-in zoom-in duration-300">
                    <div className="text-3xl font-extrabold text-slate-800 tracking-tight">
                      {format(day, 'M月d日', { locale: ja })}
                    </div>
                  </div>
                )
              }

              return (
                <div key={idx} className="flex flex-col items-center">
                  <button 
                    onClick={() => {
                      setSelectedDate(day);
                    }}
                    className={`
                      w-10 h-10 flex flex-col items-center justify-center rounded-xl transition-all relative
                      ${isSelected ? 'bg-emerald-500 text-white shadow-md shadow-emerald-200 scale-105 z-10' : 'text-slate-700 hover:bg-slate-50'}
                      ${!isCurrentMonth ? 'opacity-30' : ''}
                    `}
                  >
                    <span className={`text-sm font-bold ${isSelected ? 'text-white' : isTodayDate ? 'text-emerald-600' : ''}`}>
                      {format(day, 'd')}
                    </span>
                    {medsForDay > 0 && !isSelected && (
                       <div className={`w-1.5 h-1.5 rounded-full mt-0.5 ${allDone ? 'bg-emerald-400' : someDone ? 'bg-orange-300' : 'bg-slate-200'}`}></div>
                    )}
                    {medsForDay > 0 && isSelected && (
                       <div className="w-1.5 h-1.5 rounded-full mt-0.5 bg-white/80"></div>
                    )}
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* Task List */}
      <div className="flex-1 overflow-y-auto px-4 py-6 space-y-4">
        <div className="flex items-center justify-between px-1">
          <h3 className="text-lg font-bold text-slate-800">
            {format(selectedDate, 'M月d日 (EE)', { locale: ja })}
            <span className="text-slate-400 text-sm font-normal ml-2">のタスク</span>
          </h3>
        </div>

        {medications.length === 0 ? (
          <div className="text-center py-12 bg-white rounded-3xl shadow-sm border border-slate-100 mx-2">
             <div className="bg-slate-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                <Pill className="text-slate-300" size={32} />
             </div>
             <p className="text-slate-500 font-medium mb-3">お薬が登録されていません</p>
             <button onClick={() => setView('meds')} className="text-emerald-600 font-bold text-sm bg-emerald-50 px-4 py-2 rounded-full hover:bg-emerald-100 transition-colors">
               登録する
             </button>
          </div>
        ) : (
          medications.map(med => {
            const completed = isCompleted(med.id, selectedDate);
            const expanded = showDetailId === med.id;

            return (
              <div 
                key={med.id} 
                className={`
                  relative overflow-hidden rounded-2xl shadow-sm border transition-all duration-300
                  ${completed 
                    ? 'bg-emerald-50/50 border-emerald-100' 
                    : 'bg-white border-slate-100 hover:border-emerald-200 hover:shadow-md'
                  }
                `}
              >
                <div className="p-4 flex items-center gap-4">
                  <button 
                    onClick={() => toggleComplete(med.id, selectedDate)}
                    className={`
                      flex-shrink-0 w-12 h-12 rounded-xl flex items-center justify-center transition-all active:scale-90
                      ${completed 
                        ? 'bg-emerald-500 text-white shadow-sm shadow-emerald-200' 
                        : 'bg-slate-100 text-slate-300 hover:bg-slate-200'
                      }
                    `}
                  >
                    <Check size={28} strokeWidth={3} className={`transition-transform duration-300 ${completed ? 'scale-100' : 'scale-0'}`} />
                  </button>

                  <div className="flex-1 cursor-pointer" onClick={() => setShowDetailId(expanded ? null : med.id)}>
                    <div className="flex justify-between items-start mb-1">
                      <h4 className={`font-bold text-lg leading-tight transition-colors ${completed ? 'text-slate-400 line-through decoration-2 decoration-slate-300' : 'text-slate-800'}`}>
                        {med.title}
                      </h4>
                      <span className={`text-[10px] font-bold px-2 py-1 rounded-md border ${LABEL_COLORS[med.label] || 'bg-gray-100 border-gray-200'}`}>
                        {med.label}
                      </span>
                    </div>
                    <div className="flex items-center gap-3 text-xs font-medium text-slate-500">
                      <span className="flex items-center gap-1">
                         <Pill size={12} /> {med.dosage}{med.unit}
                      </span>
                      {med.notificationTime && (
                        <span className="flex items-center gap-1">
                           <Bell size={12} /> {med.notificationTime}
                        </span>
                      )}
                    </div>
                  </div>
                </div>

                <div className={`bg-slate-50 border-t border-slate-100 transition-all duration-300 ease-in-out ${expanded ? 'max-h-40 opacity-100' : 'max-h-0 opacity-0'}`}>
                   <div className="p-4 space-y-3">
                      <div className="flex justify-between items-center text-sm">
                         <span className="text-slate-500 font-medium">在庫数</span>
                         <span className={`font-bold ${med.stock <= 5 ? 'text-red-500' : 'text-slate-700'}`}>
                            あと {med.stock} {med.unit}
                         </span>
                      </div>
                      {med.memo && (
                        <div className="flex gap-2 text-sm text-slate-600 bg-white p-2 rounded-lg border border-slate-100">
                           <AlertCircle size={16} className="text-orange-400 shrink-0 mt-0.5" />
                           {med.memo}
                        </div>
                      )}
                   </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );

  const renderMeds = () => (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Page Header (New) */}
      <div className="bg-slate-50/80 backdrop-blur-sm border-b border-slate-200 py-3 safe-top">
         <h1 className="text-center font-bold text-slate-800">薬一覧</h1>
      </div>

      <div className="bg-white px-5 py-4 shadow-sm sticky top-0 z-10 flex justify-between items-center rounded-b-3xl border-b border-slate-100">
        <h2 className="text-xl font-extrabold text-slate-800">お薬一覧</h2>
        <button 
          onClick={() => {
            setEditingMed(null);
            setIsFormOpen(true);
          }}
          className="bg-emerald-600 text-white px-4 py-2.5 rounded-full text-sm font-bold shadow-lg shadow-emerald-200 hover:bg-emerald-700 active:scale-95 transition-all flex items-center gap-1.5"
        >
          <Plus size={18} strokeWidth={3} /> 追加
        </button>
      </div>

      <div className="p-4 space-y-3 overflow-y-auto pb-32">
        {medications.length === 0 ? (
           <div className="flex flex-col items-center justify-center h-[50vh] text-slate-400">
              <div className="bg-slate-100 p-6 rounded-full mb-4">
                <Archive size={40} className="opacity-50"/>
              </div>
              <p className="font-medium">登録されたお薬はありません</p>
           </div>
        ) : (
          medications.map(med => (
            <div 
              key={med.id} 
              onClick={() => {
                setEditingMed(med);
                setIsFormOpen(true);
              }}
              className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex justify-between items-center active:bg-slate-50 transition-colors cursor-pointer"
            >
              <div>
                <div className="flex items-center gap-2 mb-2">
                   <h3 className="font-bold text-lg text-slate-800">{med.title}</h3>
                   <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${LABEL_COLORS[med.label] || 'bg-gray-100 border-gray-200'}`}>{med.label}</span>
                </div>
                <div className="text-sm text-slate-500 font-medium flex items-center gap-3">
                  <span className={`${med.stock < 5 ? 'text-red-500 font-bold' : 'text-slate-600'}`}>
                    残り {med.stock}{med.unit}
                  </span>
                  <span className="w-1 h-1 rounded-full bg-slate-300"></span>
                  <span>1回 {med.dosage}{med.unit}</span>
                </div>
              </div>
              <ChevronRight size={20} className="text-slate-300" />
            </div>
          ))
        )}
      </div>
    </div>
  );

  const renderSettings = () => (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Page Header (New) */}
      <div className="bg-slate-50/80 backdrop-blur-sm border-b border-slate-200 py-3 safe-top">
         <h1 className="text-center font-bold text-slate-800">設定</h1>
      </div>

      <div className="bg-white px-5 py-4 shadow-sm sticky top-0 z-10 rounded-b-3xl border-b border-slate-100">
        <h2 className="text-xl font-extrabold text-slate-800 flex items-center gap-2">
           <SettingsIcon size={24} className="text-slate-400"/>
           設定詳細
        </h2>
      </div>

      <div className="p-5 space-y-8 overflow-y-auto pb-32">
        <section className="space-y-3">
           <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">カスタマイズ</h3>
           <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
              <button 
                onClick={() => setShowCustomizeModal(true)}
                className="w-full p-4 flex items-center justify-between hover:bg-slate-50 transition-colors"
              >
                <div className="flex items-center gap-3">
                   <div className="p-2.5 bg-emerald-50 text-emerald-600 rounded-xl"><SlidersHorizontal size={20}/></div>
                   <div className="text-left">
                      <p className="font-bold text-slate-800">表示のカスタマイズ</p>
                      <p className="text-xs text-slate-500 font-medium">単位やタイミングの選択肢を編集</p>
                   </div>
                </div>
                <ChevronRight size={20} className="text-slate-300" />
              </button>
           </div>
        </section>

        <section className="space-y-3">
           <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">通知</h3>
           <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
              <div className="p-4 flex items-center justify-between border-b border-slate-50">
                <div className="flex items-center gap-3">
                   <div className="p-2.5 bg-yellow-50 text-yellow-600 rounded-xl"><Bell size={20}/></div>
                   <div>
                      <p className="font-bold text-slate-800">飲み忘れ通知</p>
                      <p className="text-xs text-slate-500 font-medium">指定時間にプッシュ通知を送る</p>
                   </div>
                </div>
                <div className="relative inline-flex items-center cursor-pointer">
                  <input type="checkbox" className="sr-only peer" disabled />
                  <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-emerald-500 peer-checked:after:translate-x-full peer-checked:after:border-white"></div>
                </div>
              </div>
              <div className="p-4 bg-slate-50/50">
                 <p className="text-xs text-slate-400 text-center">
                    ブラウザ版では通知機能は制限されています。<br/>アプリ版をご利用ください。
                 </p>
              </div>
           </div>
        </section>

        <section className="space-y-3">
           <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">データ管理</h3>
           <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden divide-y divide-slate-50">
              <button 
                onClick={() => {
                   const data = JSON.stringify({ medications, logs }, null, 2);
                   const blob = new Blob([data], { type: 'application/json' });
                   const url = URL.createObjectURL(blob);
                   const a = document.createElement('a');
                   a.href = url;
                   a.download = `medimate_backup_${format(new Date(), 'yyyyMMdd')}.json`;
                   a.click();
                }}
                className="w-full p-4 flex items-center gap-3 hover:bg-slate-50 transition-colors text-left"
              >
                 <div className="p-2.5 bg-blue-50 text-blue-500 rounded-xl"><Database size={20}/></div>
                 <div>
                    <p className="font-bold text-slate-800">バックアップを保存</p>
                    <p className="text-xs text-slate-500 font-medium">現在のデータをJSONでダウンロード</p>
                 </div>
              </button>

              <button 
                onClick={() => {
                   if(window.confirm('すべてのデータを削除して初期化しますか？この操作は取り消せません。')) {
                      localStorage.clear();
                      setMedications([]);
                      setLogs([]);
                      alert('データを初期化しました');
                   }
                }}
                className="w-full p-4 flex items-center gap-3 hover:bg-red-50 transition-colors text-left"
              >
                 <div className="p-2.5 bg-red-50 text-red-500 rounded-xl"><RotateCcw size={20}/></div>
                 <div>
                    <p className="font-bold text-red-600">データを初期化</p>
                    <p className="text-xs text-slate-500 font-medium">すべての記録を消去する</p>
                 </div>
              </button>
           </div>
        </section>

        <div className="text-center pt-8 pb-4">
           <p className="text-xs font-bold text-slate-300">MediMate v1.3.0</p>
        </div>
      </div>
    </div>
  );

  return (
    <div className="bg-slate-100 min-h-screen text-slate-900 font-sans max-w-md mx-auto shadow-2xl overflow-hidden relative">
      <div className="h-full overflow-hidden">
        {view === 'home' && renderHome()}
        {view === 'meds' && renderMeds()}
        {view === 'settings' && renderSettings()}
      </div>

      <BottomNav currentView={view} onChange={setView} />

      {isFormOpen && (
        <MedicationForm 
          initialData={editingMed || undefined}
          onSave={handleSaveMed}
          onCancel={() => {
            setIsFormOpen(false);
            setEditingMed(null);
          }}
          onDelete={handleDeleteMed}
          visibleUnits={visibleUnits}
          visibleLabels={visibleLabels}
        />
      )}

      {showCustomizeModal && <CustomizeModal />}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { format, startOfWeek, addDays, isSameDay, startOfMonth, endOfMonth, endOfWeek, eachDayOfInterval, addMonths, subMonths, isToday, addWeeks, subWeeks } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Plus, Check, Pill, Archive, Bell, AlertCircle, Settings as SettingsIcon, Database, RotateCcw, SlidersHorizontal, X } from 'lucide-react';
import { BottomNav } from './components/BottomNav';
import { MedicationForm } from './components/MedicationForm';
import { Medication, MedicationLog, ViewMode, CalendarMode } from './types';
import { LABEL_COLORS, WEEK_DAYS, UNITS, LABELS } from './constants';

const App: React.FC = () => {
  // --- State ---
  const [view, setView] = useState<ViewMode>('home');

  // Calendar State
  const [selectedDate, setSelectedDate] = useState(new Date()); // タスクを表示する日付
  const [displayDate, setDisplayDate] = useState(new Date());   // カレンダーが表示している月/週の基準日
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('week');

  // Data State
  const [medications, setMedications] = useState<Medication[]>([]);
  const [logs, setLogs] = useState<MedicationLog[]>([]);

  // Preferences State
  const [visibleUnits, setVisibleUnits] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('visibleUnits');
      return saved ? JSON.parse(saved) : UNITS;
    } catch { return UNITS; }
  });
  const [visibleLabels, setVisibleLabels] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('visibleLabels');
      return saved ? JSON.parse(saved) : LABELS;
    } catch { return LABELS; }
  });

  // UI State
  const [editingMed, setEditingMed] = useState<Medication | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [showDetailId, setShowDetailId] = useState<string | null>(null);
  const [showCustomizeModal, setShowCustomizeModal] = useState(false);

  // --- Effects (Persistence) ---
  useEffect(() => {
    try {
      const savedMeds = localStorage.getItem('medications');
      const savedLogs = localStorage.getItem('logs');
      if (savedMeds) setMedications(JSON.parse(savedMeds));
      if (savedLogs) setLogs(JSON.parse(savedLogs));
    } catch (e) {
      console.error("Failed to load data", e);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('medications', JSON.stringify(medications));
  }, [medications]);

  useEffect(() => {
    localStorage.setItem('logs', JSON.stringify(logs));
  }, [logs]);

  useEffect(() => {
    localStorage.setItem('visibleUnits', JSON.stringify(visibleUnits));
  }, [visibleUnits]);

  useEffect(() => {
    localStorage.setItem('visibleLabels', JSON.stringify(visibleLabels));
  }, [visibleLabels]);

  // --- Logic Helpers ---
  const handleSaveMed = (med: Medication) => {
    if (editingMed) {
      setMedications(prev => prev.map(m => m.id === med.id ? med : m));
    } else {
      setMedications(prev => [...prev, med]);
    }
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const handleDeleteMed = (id: string) => {
    setMedications(prev => prev.filter(m => m.id !== id));
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const toggleComplete = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    const existingLog = logs.find(l => l.medicationId === medId && l.dateStr === dateStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existingLog) {
      // Untoggle: Remove log and restore stock
      setLogs(prev => prev.filter(l => l.id !== existingLog.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      // Toggle: Add log and decrease stock
      const newLog: MedicationLog = {
        id: crypto.randomUUID(),
        medicationId: medId,
        timestamp: new Date().getTime(),
        dateStr
      };
      setLogs(prev => [...prev, newLog]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  const isCompleted = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dateStr);
  };

  const handleCalendarNavigate = (direction: 'prev' | 'next') => {
    if (calendarMode === 'day') {
      const newDate = direction === 'next' ? addDays(selectedDate, 1) : addDays(selectedDate, -1);
      setSelectedDate(newDate);
      setDisplayDate(newDate);
    } else if (calendarMode === 'week') {
      setDisplayDate(prev => direction === 'next' ? addWeeks(prev, 1) : subWeeks(prev, 1));
    } else {
      setDisplayDate(prev => direction === 'next' ? addMonths(prev, 1) : subMonths(prev, 1));
    }
  };

  // --- Calendar Generators ---
  const generateCalendarDays = () => {
    if (calendarMode === 'day') {
      return [selectedDate];
    }
    if (calendarMode === 'week') {
      const start = startOfWeek(displayDate, { weekStartsOn: 0 }); // Sunday start
      return Array.from({ length: 7 }).map((_, i) => addDays(start, i));
    }
    // Month
    const start = startOfWeek(startOfMonth(displayDate), { weekStartsOn: 0 });
    const end = endOfWeek(endOfMonth(displayDate), { weekStartsOn: 0 });
    return eachDayOfInterval({ start, end });
  };

  const calendarDays = generateCalendarDays();

  // --- Customize Modal ---
  const CustomizeModal = () => {
    const [activeTab, setActiveTab] = useState<'timing' | 'unit'>('timing');

    const toggleUnit = (u: string) => {
      setVisibleUnits(prev => prev.includes(u) ? prev.filter(x => x !== u) : [...prev, u]);
    };

    const toggleLabel = (l: string) => {
      setVisibleLabels(prev => prev.includes(l) ? prev.filter(x => x !== l) : [...prev, l]);
    };

    return (
      <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 animate-in fade-in duration-200">
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowCustomizeModal(false)}></div>
        <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm flex flex-col max-h-[80vh] relative z-10 animate-in zoom-in-95 duration-200">
          <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-2xl">
            <h3 className="font-bold text-slate-800">表示のカスタマイズ</h3>
            <button onClick={() => setShowCustomizeModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
          </div>

          <div className="flex p-2 gap-2 bg-slate-50 border-b border-slate-100">
            <button 
              onClick={() => setActiveTab('timing')}
              className={`flex-1 py-2 text-sm font-bold rounded-lg transition-colors ${activeTab === 'timing' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
            >
              服薬タイミング
            </button>
            <button 
              onClick={() => setActiveTab('unit')}
              className={`flex-1 py-2 text-sm font-bold rounded-lg transition-colors ${activeTab === 'unit' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
            >
              単位
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-2">
            {activeTab === 'timing' ? (
              <div className="space-y-1">
                {LABELS.map(label => (
                  <label key={label} className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 cursor-pointer">
                    <span className="font-bold text-slate-700">{label}</span>
                    <div className="relative inline-flex items-center">
                      <input 
                        type="checkbox" 
                        checked={visibleLabels.includes(label)}
                        onChange={() => toggleLabel(label)}
                        className="sr-only peer" 
                      />
                      <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:bg-emerald-500 after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:after:translate-x-full peer-checked:after:border-white"></div>
                    </div>
                  </label>
                ))}
              </div>
            ) : (
              <div className="space-y-1">
                {UNITS.map(unit => (
                  <label key={unit} className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 cursor-pointer">
                    <span className="font-bold text-slate-700">{unit}</span>
                    <div className="relative inline-flex items-center">
                      <input 
                        type="checkbox" 
                        checked={visibleUnits.includes(unit)}
                        onChange={() => toggleUnit(unit)}
                        className="sr-only peer" 
                      />
                      <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:bg-emerald-500 after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:after:translate-x-full peer-checked:after:border-white"></div>
                    </div>
                  </label>
                ))}
              </div>
            )}
          </div>

          <div className="p-4 border-t border-slate-100 bg-slate-50 rounded-b-2xl">
             <button onClick={() => setShowCustomizeModal(false)} className="w-full bg-emerald-600 text-white font-bold py-3 rounded-xl shadow-lg shadow-emerald-200">完了</button>
          </div>
        </div>
      </div>
    );
  };

  // --- Renders ---

  const renderHome = () => (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Page Header */}
      <div className="bg-slate-50/80 backdrop-blur-sm border-b border-slate-200 py-3 safe-top">
         <h1 className="text-center font-bold text-slate-800">ホーム</h1>
      </div>

      {/* Calendar Header & Control */}
      <div className="bg-white shadow-sm z-10 sticky top-0 rounded-b-3xl border-b border-slate-100">
        <div className="px-5 pt-4 pb-2">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-extrabold text-slate-800 flex items-center gap-2">
              <CalendarIcon className="text-emerald-600" size={24} />
              {calendarMode === 'day' 
                ? format(selectedDate, 'M月d日', { locale: ja }) 
                : format(displayDate, 'yyyy年 M月', { locale: ja })}
            </h2>
            <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1">
               <button 
                  onClick={() => setCalendarMode('month')} 
                  className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${calendarMode === 'month' ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>月</button>
               <button 
                  onClick={() => {
                    setCalendarMode('week');
                    setDisplayDate(selectedDate);
                  }} 
                  className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${calendarMode === 'week' ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>週</button>
               <button 
                  onClick={() => {
                    setCalendarMode('day');
                    setDisplayDate(selectedDate);
                  }} 
                  className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${calendarMode === 'day' ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>日</button>
            </div>
          </div>

          <div className="flex justify-between items-center mb-2">
             <button onClick={() => handleCalendarNavigate('prev')} className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors"><ChevronLeft size={20}/></button>
             <button onClick={() => {
               const now = new Date();
               setSelectedDate(now);
               setDisplayDate(now);
             }} className="text-xs font-bold text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full hover:bg-emerald-100 transition-colors">今日に戻る</button>
             <button onClick={() => handleCalendarNavigate('next')} className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors"><ChevronRight size={20}/></button>
          </div>

          <div className={`grid ${calendarMode === 'month' ? 'grid-cols-7 gap-y-1' : calendarMode === 'week' ? 'grid-cols-7' : 'grid-cols-1'} text-center pb-4`}>
            {calendarMode !== 'day' && WEEK_DAYS.map((day, i) => (
              <div key={day} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{day}</div>
            ))}

            {calendarDays.map((day, idx) => {
              const isSelected = isSameDay(day, selectedDate);
              const isTodayDate = isToday(day);
              const isCurrentMonth = calendarMode !== 'month' || format(day, 'M') === format(displayDate, 'M');

              const dayStr = format(day, 'yyyy-MM-dd');
              const medsForDay = medications.length;
              const completedCount = logs.filter(l => l.dateStr === dayStr && medications.some(m => m.id === l.medicationId)).length;
              const allDone = medsForDay > 0 && medsForDay === completedCount;
              const someDone = completedCount > 0;

              if (calendarMode === 'day') {
                return (
                  <div key={idx} className="flex flex-col items-center justify-center py-6 animate-in fade-in zoom-in duration-300">
                    <div className="text-3xl font-extrabold text-slate-800 tracking-tight">
                      {format(day, 'M月d日', { locale: ja })}
                    </div>
                  </div>
                )
              }

              return (
                <div key={idx} className="flex flex-col items-center">
                  <button 
                    onClick={() => {
                      setSelectedDate(day);
                    }}
                    className={`
                      w-10 h-10 flex flex-col items-center justify-center rounded-xl transition-all relative
                      ${isSelected ? 'bg-emerald-500 text-white shadow-md shadow-emerald-200 scale-105 z-10' : 'text-slate-700 hover:bg-slate-50'}
                      ${!isCurrentMonth ? 'opacity-30' : ''}
                    `}
                  >
                    <span className={`text-sm font-bold ${isSelected ? 'text-white' : isTodayDate ? 'text-emerald-600' : ''}`}>
                      {format(day, 'd')}
                    </span>
                    {medsForDay > 0 && !isSelected && (
                       <div className={`w-1.5 h-1.5 rounded-full mt-0.5 ${allDone ? 'bg-emerald-400' : someDone ? 'bg-orange-300' : 'bg-slate-200'}`}></div>
                    )}
                    {medsForDay > 0 && isSelected && (
                       <div className="w-1.5 h-1.5 rounded-full mt-0.5 bg-white/80"></div>
                    )}
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* Task List */}
      <div className="flex-1 overflow-y-auto px-4 py-6 space-y-4">
        <div className="flex items-center justify-between px-1">
          <h3 className="text-lg font-bold text-slate-800">
            {format(selectedDate, 'M月d日 (EE)', { locale: ja })}
            <span className="text-slate-400 text-sm font-normal ml-2">のタスク</span>
          </h3>
        </div>

        {medications.length === 0 ? (
          <div className="text-center py-12 bg-white rounded-3xl shadow-sm border border-slate-100 mx-2">
             <div className="bg-slate-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                <Pill className="text-slate-300" size={32} />
             </div>
             <p className="text-slate-500 font-medium mb-3">お薬が登録されていません</p>
             <button onClick={() => setView('meds')} className="text-emerald-600 font-bold text-sm bg-emerald-50 px-4 py-2 rounded-full hover:bg-emerald-100 transition-colors">
               登録する
             </button>
          </div>
        ) : (
          medications.map(med => {
            const completed = isCompleted(med.id, selectedDate);
            const expanded = showDetailId === med.id;

            return (
              <div 
                key={med.id} 
                className={`
                  relative overflow-hidden rounded-2xl shadow-sm border transition-all duration-300
                  ${completed 
                    ? 'bg-emerald-50/50 border-emerald-100' 
                    : 'bg-white border-slate-100 hover:border-emerald-200 hover:shadow-md'
                  }
                `}
              >
                <div className="p-4 flex items-center gap-4">
                  <button 
                    onClick={() => toggleComplete(med.id, selectedDate)}
                    className={`
                      flex-shrink-0 w-12 h-12 rounded-xl flex items-center justify-center transition-all active:scale-90
                      ${completed 
                        ? 'bg-emerald-500 text-white shadow-sm shadow-emerald-200' 
                        : 'bg-slate-100 text-slate-300 hover:bg-slate-200'
                      }
                    `}
                  >
                    <Check size={28} strokeWidth={3} className={`transition-transform duration-300 ${completed ? 'scale-100' : 'scale-0'}`} />
                  </button>

                  <div className="flex-1 cursor-pointer" onClick={() => setShowDetailId(expanded ? null : med.id)}>
                    <div className="flex justify-between items-start mb-1">
                      <h4 className={`font-bold text-lg leading-tight transition-colors ${completed ? 'text-slate-400 line-through decoration-2 decoration-slate-300' : 'text-slate-800'}`}>
                        {med.title}
                      </h4>
                      <span className={`text-[10px] font-bold px-2 py-1 rounded-md border ${LABEL_COLORS[med.label] || 'bg-gray-100 border-gray-200'}`}>
                        {med.label}
                      </span>
                    </div>
                    <div className="flex items-center gap-3 text-xs font-medium text-slate-500">
                      <span className="flex items-center gap-1">
                         <Pill size={12} /> {med.dosage}{med.unit}
                      </span>
                      {med.notificationTime && (
                        <span className="flex items-center gap-1">
                           <Bell size={12} /> {med.notificationTime}
                        </span>
                      )}
                    </div>
                  </div>
                </div>

                <div className={`bg-slate-50 border-t border-slate-100 transition-all duration-300 ease-in-out ${expanded ? 'max-h-40 opacity-100' : 'max-h-0 opacity-0'}`}>
                   <div className="p-4 space-y-3">
                      <div className="flex justify-between items-center text-sm">
                         <span className="text-slate-500 font-medium">在庫数</span>
                         <span className={`font-bold ${med.stock <= 5 ? 'text-red-500' : 'text-slate-700'}`}>
                            あと {med.stock} {med.unit}
                         </span>
                      </div>
                      {med.memo && (
                        <div className="flex gap-2 text-sm text-slate-600 bg-white p-2 rounded-lg border border-slate-100">
                           <AlertCircle size={16} className="text-orange-400 shrink-0 mt-0.5" />
                           {med.memo}
                        </div>
                      )}
                   </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );

  const renderMeds = () => (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Page Header (Revised) */}
      <div className="bg-slate-50/80 backdrop-blur-sm border-b border-slate-200 py-3 safe-top relative">
         <h1 className="text-center font-bold text-slate-800">お薬一覧</h1>
         <button 
          onClick={() => {
            setEditingMed(null);
            setIsFormOpen(true);
          }}
          className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-1 text-emerald-600 font-bold text-sm bg-emerald-50 px-3 py-1.5 rounded-full hover:bg-emerald-100 transition-colors"
        >
          <Plus size={16} strokeWidth={3} /> 追加
        </button>
      </div>

      <div className="p-4 space-y-3 overflow-y-auto pb-32">
        {medications.length === 0 ? (
           <div className="flex flex-col items-center justify-center h-[50vh] text-slate-400">
              <div className="bg-slate-100 p-6 rounded-full mb-4">
                <Archive size={40} className="opacity-50"/>
              </div>
              <p className="font-medium">登録されたお薬はありません</p>
              <button 
                onClick={() => {
                  setEditingMed(null);
                  setIsFormOpen(true);
                }}
                className="mt-4 text-emerald-600 font-bold text-sm bg-white px-4 py-2 rounded-xl shadow-sm border border-emerald-100"
              >
                お薬を登録する
              </button>
           </div>
        ) : (
          medications.map(med => (
            <div 
              key={med.id} 
              onClick={() => {
                setEditingMed(med);
                setIsFormOpen(true);
              }}
              className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex justify-between items-center active:bg-slate-50 transition-colors cursor-pointer"
            >
              <div>
                <div className="flex items-center gap-2 mb-2">
                   <h3 className="font-bold text-lg text-slate-800">{med.title}</h3>
                   <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${LABEL_COLORS[med.label] || 'bg-gray-100 border-gray-200'}`}>{med.label}</span>
                </div>
                <div className="text-sm text-slate-500 font-medium flex items-center gap-3">
                  <span className={`${med.stock < 5 ? 'text-red-500 font-bold' : 'text-slate-600'}`}>
                    残り {med.stock}{med.unit}
                  </span>
                  <span className="w-1 h-1 rounded-full bg-slate-300"></span>
                  <span>1回 {med.dosage}{med.unit}</span>
                </div>
              </div>
              <ChevronRight size={20} className="text-slate-300" />
            </div>
          ))
        )}
      </div>
    </div>
  );

  const renderSettings = () => (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Page Header */}
      <div className="bg-slate-50/80 backdrop-blur-sm border-b border-slate-200 py-3 safe-top">
         <h1 className="text-center font-bold text-slate-800">設定</h1>
      </div>

      <div className="bg-white px-5 py-4 shadow-sm sticky top-0 z-10 rounded-b-3xl border-b border-slate-100">
        <h2 className="text-xl font-extrabold text-slate-800 flex items-center gap-2">
           <SettingsIcon size={24} className="text-slate-400"/>
           設定詳細
        </h2>
      </div>

      <div className="p-5 space-y-8 overflow-y-auto pb-32">
        <section className="space-y-3">
           <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">カスタマイズ</h3>
           <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
              <button 
                onClick={() => setShowCustomizeModal(true)}
                className="w-full p-4 flex items-center justify-between hover:bg-slate-50 transition-colors"
              >
                <div className="flex items-center gap-3">
                   <div className="p-2.5 bg-emerald-50 text-emerald-600 rounded-xl"><SlidersHorizontal size={20}/></div>
                   <div className="text-left">
                      <p className="font-bold text-slate-800">表示のカスタマイズ</p>
                      <p className="text-xs text-slate-500 font-medium">単位やタイミングの選択肢を編集</p>
                   </div>
                </div>
                <ChevronRight size={20} className="text-slate-300" />
              </button>
           </div>
        </section>

        <section className="space-y-3">
           <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">通知</h3>
           <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
              <div className="p-4 flex items-center justify-between border-b border-slate-50">
                <div className="flex items-center gap-3">
                   <div className="p-2.5 bg-yellow-50 text-yellow-600 rounded-xl"><Bell size={20}/></div>
                   <div>
                      <p className="font-bold text-slate-800">飲み忘れ通知</p>
                      <p className="text-xs text-slate-500 font-medium">指定時間にプッシュ通知を送る</p>
                   </div>
                </div>
                <div className="relative inline-flex items-center cursor-pointer">
                  <input type="checkbox" className="sr-only peer" disabled />
                  <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-emerald-500 peer-checked:after:translate-x-full peer-checked:after:border-white"></div>
                </div>
              </div>
              <div className="p-4 bg-slate-50/50">
                 <p className="text-xs text-slate-400 text-center">
                    ブラウザ版では通知機能は制限されています。<br/>アプリ版をご利用ください。
                 </p>
              </div>
           </div>
        </section>

        <section className="space-y-3">
           <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">データ管理</h3>
           <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden divide-y divide-slate-50">
              <button 
                onClick={() => {
                   const data = JSON.stringify({ medications, logs }, null, 2);
                   const blob = new Blob([data], { type: 'application/json' });
                   const url = URL.createObjectURL(blob);
                   const a = document.createElement('a');
                   a.href = url;
                   a.download = `medimate_backup_${format(new Date(), 'yyyyMMdd')}.json`;
                   a.click();
                }}
                className="w-full p-4 flex items-center gap-3 hover:bg-slate-50 transition-colors text-left"
              >
                 <div className="p-2.5 bg-blue-50 text-blue-500 rounded-xl"><Database size={20}/></div>
                 <div>
                    <p className="font-bold text-slate-800">バックアップを保存</p>
                    <p className="text-xs text-slate-500 font-medium">現在のデータをJSONでダウンロード</p>
                 </div>
              </button>

              <button 
                onClick={() => {
                   if(window.confirm('すべてのデータを削除して初期化しますか？この操作は取り消せません。')) {
                      localStorage.clear();
                      setMedications([]);
                      setLogs([]);
                      alert('データを初期化しました');
                   }
                }}
                className="w-full p-4 flex items-center gap-3 hover:bg-red-50 transition-colors text-left"
              >
                 <div className="p-2.5 bg-red-50 text-red-500 rounded-xl"><RotateCcw size={20}/></div>
                 <div>
                    <p className="font-bold text-red-600">データを初期化</p>
                    <p className="text-xs text-slate-500 font-medium">すべての記録を消去する</p>
                 </div>
              </button>
           </div>
        </section>

        <div className="text-center pt-8 pb-4">
           <p className="text-xs font-bold text-slate-300">MediMate v1.3.1</p>
        </div>
      </div>
    </div>
  );

  return (
    <div className="bg-slate-100 min-h-screen text-slate-900 font-sans max-w-md mx-auto shadow-2xl overflow-hidden relative">
      <div className="h-full overflow-hidden">
        {view === 'home' && renderHome()}
        {view === 'meds' && renderMeds()}
        {view === 'settings' && renderSettings()}
      </div>

      <BottomNav currentView={view} onChange={setView} />

      {isFormOpen && (
        <MedicationForm 
          initialData={editingMed || undefined}
          onSave={handleSaveMed}
          onCancel={() => {
            setIsFormOpen(false);
            setEditingMed(null);
          }}
          onDelete={handleDeleteMed}
          visibleUnits={visibleUnits}
          visibleLabels={visibleLabels}
        />
      )}

      {showCustomizeModal && <CustomizeModal />}
    </div>
  );
};

export default App;
